import unittest
from copy import deepcopy

from config_merge import merge_config


class MergeTests(unittest.TestCase):
    def test_explicit_none_overrides_and_missing_key_stays(self):
        result = merge_config({"timeout": 30, "retries": 2}, {"timeout": None})
        self.assertEqual(result, {"timeout": None, "retries": 2})

    def test_nested_precedence_and_preserved_keys(self):
        base = {"database": {"host": "db", "port": 5432}, "enabled": True}
        result = merge_config(base, {"database": {"port": 5433}})
        self.assertEqual(result, {
            "database": {"host": "db", "port": 5433}, "enabled": True
        })

    def test_inputs_are_not_modified(self):
        base = {"database": {"host": "db", "port": 5432}, "enabled": True}
        overrides = {"database": {"port": 5433}, "enabled": False}
        original_base, original_overrides = deepcopy(base), deepcopy(overrides)
        merge_config(base, overrides)
        self.assertEqual(base, original_base)
        self.assertEqual(overrides, original_overrides)

    def test_result_owns_nested_lists_from_both_inputs(self):
        base = {"base_names": ["base"]}
        overrides = {"feature": {"names": ["override"]}}
        result = merge_config(base, overrides)
        result["base_names"].append("changed")
        result["feature"]["names"].append("changed")
        self.assertEqual(base, {"base_names": ["base"]})
        self.assertEqual(overrides, {"feature": {"names": ["override"]}})

    def test_non_dictionary_values_replace(self):
        result = merge_config({"value": {"old": True}}, {"value": [1, 2]})
        self.assertEqual(result, {"value": [1, 2]})

    def test_empty_nested_override_preserves_base(self):
        base = {"database": {"host": "db"}}
        result = merge_config(base, {"database": {}})
        self.assertEqual(result, base)
        result["database"]["host"] = "other"
        self.assertEqual(base["database"]["host"], "db")

